import Foundation
@testable import DockGroupsCore

/// Files written by version 0.9.0 (`2ea08df`), byte for byte: the preferences file with the
/// preferences of `Version080Fixtures` (every setting changed, a protected app) and with the
/// defaults, the groups file of a group as capturing the open apps makes one (`capturedGroup`: two
/// apps by bundle identifier with their locations, one app without a bundle identifier, identified
/// by its location, and one run from a temporary copy, kept without a location), and that group's
/// agent configuration. Generated by building that version's DockGroupsCore and saving these values
/// with it.
///
/// `preferencesFileWithCapture` and `defaultPreferencesFileWithCapture` are what this version
/// writes for the same preferences once the capture settings aren't the defaults. Read by that
/// build of 0.9.0 and saved again, they gave `preferencesFile` and `defaultPreferencesFile` back
/// byte for byte: 0.9.0 ignores the `capture` key, and drops it when it saves. The groups file is
/// the same in both versions: capturing adds nothing to it.
enum Version090PreferencesFixtures {
    /// Capture settings that differ from the defaults in both values.
    static let capture = CaptureSettings(order: .name, selectsOnlyAppsWithWindows: true)

    static var preferencesWithCapture: PopupPreferences {
        var preferences = Version080Fixtures.preferences
        preferences.capture = capture
        return preferences
    }

    static var defaultPreferencesWithCapture: PopupPreferences {
        var preferences = PopupPreferences()
        preferences.capture = capture
        return preferences
    }

